    let mut prefix=G::new("validator-wire-prefix",vec![SemanticType::Bytes,rows()],vec![seq(),int()]);let zero=prefix.n(0);let empty=prefix.op(Operation::MakeArray,vec![],seq());let prefix_out=prefix.loop_node("validator-wire-prefix",prefix_state,vec![input(0),input(1),zero.clone(),zero,empty]);
    let key_args=vec![SemanticType::Bytes,rows(),seq(),int(),int(),int(),int(),int()];
    let mut nk=G::new("validator-wire-node-key",key_args.clone(),vec![int()]);let index=call(&mut nk,"validator-node-index-fast",vec![input(1),input(6)],int());let offset=nk.index(input(2),index.clone());let node=nk.index(input(1),index);let list=nk.field(node,3);let rank=call(&mut nk,"validator-port-rank-fast",vec![input(0),list,input(7)],int());let node_key=nk.arithmetic(Operation::Add,offset,rank);
    let mut gk=G::new("validator-wire-graph-key",key_args.clone(),vec![int()]);let rank=call(&mut gk,"validator-port-rank-fast",vec![input(0),input(4),input(7)],int());let graph_key=gk.arithmetic(Operation::Add,input(3),rank);
    let mut key=G::new("validator-wire-key",key_args,vec![int()]);let zero=key.n(0);let is_node=key.compare(Operation::Eq,input(5),zero);let key_slot=choose_integer(&mut key,"validator-wire-node-key","validator-wire-graph-key",is_node,(0..8).map(input).collect());
    let byte=SemanticType::Integer(IntegerType{min:0,max:255});let byte_seq=SemanticType::Slice(Box::new(byte.clone()));
    let mut zero_byte=G::new("validator-wire-zero-byte",vec![int()],vec![byte.clone()]);let z=zero_byte.n(0);
    let mut mark=G::new("validator-wire-mark",vec![SemanticType::Bytes,int()],vec![SemanticType::Bytes]);let zero=mark.n(0);let before=mark.op(Operation::BytesSlice,vec![(input(0),SemanticType::Bytes),(zero,int()),(input(1),int())],SemanticType::Bytes);let next=mark.advance(input(1),1);let len=mark.length(input(0));let remaining=mark.arithmetic(Operation::Sub,len,next.clone());let after=mark.op(Operation::BytesSlice,vec![(input(0),SemanticType::Bytes),(next,int()),(remaining,int())],SemanticType::Bytes);let one=mark.op(Operation::Const(Literal::Bytes(vec![1])),vec![],SemanticType::Bytes);let first=mark.op(Operation::BytesConcat,vec![(before,SemanticType::Bytes),(one,SemanticType::Bytes)],SemanticType::Bytes);let marked=mark.op(Operation::BytesConcat,vec![(first,SemanticType::Bytes),(after,SemanticType::Bytes)],SemanticType::Bytes);
