    let mut body=G::new("validator-wire-visit-body",state.clone(),state.clone());let edge=body.index(input(2),input(7));let kind=body.field(edge.clone(),3);let node=body.field(edge.clone(),4);let endpoint_port=body.field(edge,5);let slot=call(&mut body,"validator-wire-key",vec![input(0),input(1),input(5),input(6),input(4),kind,node,endpoint_port],int());
